//! Verifier-only structured transpose of SPEC §5 monomial-truncated L*q.
//! Prover/reference formulas remain in chord.rs. Work buffers are caller-owned.
use super::{chord::Secant, Error};
use crate::field::{M31, QM31 as E, QM31};
mod table {
    include!("../r0/top_overflow.rs");
}

/// [X^j] N_j, generated by the leading-coefficient recurrence
/// lead(D_(b+1))=2*lead(D_b)^2 and N_j's product definition.
pub fn leading(j: usize) -> M31 {
    let mut out = M31::ONE;
    let mut d = M31::ONE;
    let mut bits = j;
    while bits != 0 {
        if bits & 1 != 0 {
            out = out.mul(d);
        }
        bits >>= 1;
        d = d.mul(d).double();
    }
    out
}
/// M[510,j] and M[511,j]. Degree and parity annihilate all other columns.
pub fn top_rows(j: usize) -> [M31; 2] {
    [
        if j == 510 { leading(510) } else { M31::ZERO },
        if j == 511 { leading(511) } else { M31::ZERO },
    ]
}

/// Transpose of T_X = M^-1 trunc_512(X M ·). The sole top-factor
/// overflow is D_9 in column 511, replaced by its fixed truncated row.
/// A carry clears the occupied bit, adds the constant half, then continues
/// with the next D bit: D_b²=(D_(b+1)+1)/2.
pub fn x_transpose(input: &[E], output: &mut [E]) -> Result<(), Error> {
    if input.len() != 512 || output.len() != 512 {
        return Err(Error::WrongLength);
    }
    x_transpose_by(|j| input[j], output)
}
/// Extensible linear-weight primitive; it does not know the number or origin
/// of input claim rows. w is interleaved (even, odd) and overwritten in place.
/// Scratch: three 512-entry E slices, 48 KiB total; no dense basis.
pub fn quotient_weights(
    line: Secant<QM31>,
    w: &mut [E],
    even: &mut [E],
    odd: &mut [E],
    twice: &mut [E],
) -> Result<(), Error> {
    if w.len() != 1024 || even.len() != 512 || odd.len() != 512 || twice.len() != 512 {
        return Err(Error::WrongLength);
    }
    // Deinterleave into scratch. Use the other two buffers successively so
    // only three half-vectors, plus w itself, are ever live.
    for j in 0..512 {
        twice[j] = w[2 * j];
    }
    x_transpose(twice, even)?;
    x_transpose(even, twice)?;
    // odd is needed as input; its transpose can temporarily occupy w's odd
    // slots only after preserving them. Instead use an interleaved reader
    // specialization that leaves w intact.
    x_transpose_interleaved_odd(w, odd)?;
    for j in 0..512 {
        let we = w[2 * j];
        let wo = w[2 * j + 1];
        w[2 * j] = we.mul(line.a).add(even[j].mul(line.b)).add(wo.mul(line.c));
        w[2 * j + 1] = wo
            .mul(line.a)
            .add(odd[j].mul(line.b))
            .add(we.sub(twice[j]).mul(line.c));
    }
    Ok(())
}
fn x_transpose_interleaved_odd(input: &[E], output: &mut [E]) -> Result<(), Error> {
    // Same sparse columns as x_transpose, with an interleaved input view.
    x_transpose_by(|j| input[2 * j + 1], output)
}
fn x_transpose_by(mut at: impl FnMut(usize) -> E, output: &mut [E]) -> Result<(), Error> {
    if output.len() != 512 {
        return Err(Error::WrongLength);
    }
    for j in 0..512 {
        let (mut rest, mut bit, mut factor, mut sum) = (j, 1, M31::ONE, E::ZERO);
        loop {
            if bit == 512 {
                let mut overflow = E::ZERO;
                for (k, &c) in table::TOP_OVERFLOW.iter().enumerate() {
                    if c != 0 {
                        overflow = overflow.add(at(k).mul_m31(M31(c)));
                    }
                }
                sum = sum.add(overflow.mul_m31(factor));
                break;
            }
            if rest & bit == 0 {
                sum = sum.add(at(rest | bit).mul_m31(factor));
                break;
            }
            rest ^= bit;
            factor = factor.mul(M31(1_073_741_824));
            sum = sum.add(at(rest).mul_m31(factor));
            bit *= 2;
        }
        output[j] = sum;
    }
    Ok(())
}
